test('project task UI: labels, validation, completion, and filters in creation order', async () => {
  const app = new Node('main');
  const tasks = [];
  const context = {
    document: {
      querySelector: () => app,
      createElement: (tag) => new Node(tag),
    },
    location: { pathname: '/projects/1', assign() {} },
    async fetch(path, options) {
      let data;
      if (path === '/api/projects/1') data = { id: 1, name: 'Example' };
      else if (!options) data = tasks.map((task) => ({ ...task }));
      else if (options.method === 'POST') {
        data = { id: tasks.length + 1, title: JSON.parse(options.body).title, completed: false };
        tasks.push({ ...data });
      } else {
        const task = tasks.find((task) => path.endsWith(`/${task.id}`));
        Object.assign(task, JSON.parse(options.body));
        data = { ...task };
      }
      return { ok: true, json: async () => data };
    },
  };
  runInNewContext(source, context);
  // The controller's initial render completes through promise microtasks.
  await new Promise((resolve) => setImmediate(resolve));
  assert.equal(app.querySelector('h1').textContent, 'Example');
  const form = app.querySelector('form');
  const [label, input, button] = form.children;
  assert.equal(label.textContent, 'Task title');
  assert.equal(label.htmlFor, input.id);
  assert.equal(button.textContent, 'Create task');
  const filter = app.querySelector('select');
  assert.equal(filter.value, 'All');
  assert.deepEqual(filter.children.map((option) => option.textContent), ['All', 'Open', 'Completed']);
  const list = app.querySelector('ul');
  input.value = ' \t\n ';
  await form.fire('submit');
  assert.equal(app.querySelector('[role="alert"]').textContent, 'Task title is required');
  assert.equal(list.children.length, 0);
  for (const title of ['  First  ', 'Second']) {
    input.value = title;
    await form.fire('submit');
  }
  assert.equal(app.querySelector('[role="alert"]'), undefined);
  const titles = () => list.children.map((row) => row.children[1].textContent);
  assert.deepEqual(titles(), ['First', 'Second']);
  assert.ok(list.children.every((row) => row.dataset.testid === 'task-row'));
  let checkbox = list.children[0].children[0];
  assert.equal(checkbox.attributes['aria-label'], 'Complete First');
  assert.equal(checkbox.checked, false);
  checkbox.checked = true;
  await checkbox.fire('change');
  assert.equal(tasks[0].completed, true);
  filter.value = 'Open';
  await filter.fire('change');
  assert.deepEqual(titles(), ['Second']);
  filter.value = 'Completed';
  await filter.fire('change');
  assert.deepEqual(titles(), ['First']);
  checkbox = list.children[0].children[0];
  checkbox.checked = false;
  await checkbox.fire('change');
  assert.equal(tasks[0].completed, false);
  assert.deepEqual(titles(), []);
  filter.value = 'All';
  await filter.fire('change');
  assert.deepEqual(titles(), ['First', 'Second']);
});

:root { font-family: system-ui, sans-serif; color: #172a3a; background: #f4f6f8; }
* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 760px; margin: 60px auto; padding: 28px; background: white; border-radius: 12px; box-shadow: 0 4px 24px #172a3a12; }
h1 { margin-top: 0; overflow-wrap: anywhere; }
form { display: grid; grid-template-columns: 1fr auto; gap: 10px; }
label { grid-column: 1 / -1; font-weight: 600; }
input, button, select { font: inherit; border-radius: 6px; padding: 10px 14px; }
input { min-width: 0; border: 1px solid #8294a5; }
button { color: white; background: #245caa; border: 1px solid #245caa; cursor: pointer; }
button:hover { background: #194782; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #bd6b00; outline-offset: 3px; }
.projects { list-style: none; padding: 0; margin: 28px 0 0; }
.projects li { display: flex; align-items: center; justify-content: space-between; gap: 20px; padding: 16px 0; border-top: 1px solid #dde3e9; }
.projects span { overflow-wrap: anywhere; min-width: 0; }
.projects button { flex-shrink: 0; }
.task-filter { display: flex; align-items: center; gap: 12px; margin-top: 24px; }
.tasks { list-style: none; padding: 0; margin: 20px 0 0; }
.tasks li { display: flex; align-items: center; gap: 12px; padding: 16px 0; border-top: 1px solid #dde3e9; }
.tasks span { overflow-wrap: anywhere; min-width: 0; }
.tasks input { flex-shrink: 0; width: 20px; height: 20px; }
[role="alert"] { color: #a32121; }
@media (max-width: 600px) { main { margin: 16px; padding: 20px; } form { grid-template-columns: 1fr; } }

